// Carga el .env y muestra por pantalla todas sus variables.
import process from 'node:process';

// Guardamos las variables que ya existían para mostrar solo
// las que aporta el fichero .env.
const previas = new Set(Object.keys(process.env));

process.loadEnvFile();

for (const [clave, valor] of Object.entries(process.env)) {
  if (!previas.has(clave)) {
    console.log(`${clave}=${valor}`);
  }
}

// Carga el .env y muestra por pantalla los NOMBRES de sus variables.
// No imprime los valores para no exponer secretos.
import process from 'node:process';

const previas = new Set(Object.keys(process.env));

process.loadEnvFile();

for (const clave of Object.keys(process.env)) {
  if (!previas.has(clave)) {
    console.log(clave);
  }
}

